                _weight_step = st.slider("1走古くなるごとの重みの減少", min_value=0.00, max_value=0.20, value=0.05, step=0.01, key="geo_v41_weight_step", help="0.05なら直近から 1.00, 0.95, 0.90, 0.85, 0.80, 0.75")
                _weighted_rows = []
