            with st.expander("🔬 上がり3F診断｜単位補正後の計算確認", expanded=True):
                st.caption("上がり3Fの332→33.2秒などの単位補正を予想計算に適用しています。ここでは補正後の計算値を確認できます。")
                all_f3_rows = []
